// Independent acceptance checks for the app generated by the real OpenCode run.
// This file is outside that app; it never creates or changes its implementation.
export default async function ({ evaluate, key, click, captureScreenshot }) {
  const checks = [];
  const result = () => evaluate(() => document.querySelector("#result")?.textContent.trim());
  const expression = () => evaluate(() => document.querySelector("#expression")?.textContent.trim());
  const record = (name, actual, expected) => checks.push({ name, actual, expected, passed: actual === expected });
  const type = async (text) => { for (const character of text) await key(character); };
  const calculate = async (text, expected) => {
    await key("Escape");
    await type(text);
    await key("Enter");
    record(`keyboard ${text}`, await result(), expected);
  };

  record("Korean title", await evaluate(() => document.title), "계산기");
  await calculate("12+7", "19");
  await calculate("9-14", "-5");
  await calculate("6*7", "42");
  await calculate("7/2", "3.5");
  await calculate("2+3*4", "14");
  await calculate("(2+3)*4", "20");
  await calculate("0.1+0.2", "0.3");
  await calculate("-5+3", "-2");
  await calculate("2*-3", "-6");
  await calculate("9/0", "0으로 나눌 수 없습니다");

  await click('[data-action="clear-all"]');
  await click('[data-key="7"]');
  await click('[data-op="×"]');
  await click('[data-key="2"]');
  await click('[data-action="equals"]');
  record("mouse 7 × 2", await result(), "14");

  await key("Escape");
  await type("123");
  record("expression updates while typing", await expression(), "123");
  await key("Backspace");
  record("Backspace updates expression", await expression(), "12");
  await key("Enter");
  record("Backspace changes calculation", await result(), "12");
  await key("+");
  await key("3");
  await key("Enter");
  record("continue after equals", await result(), "15");
  await key("4");
  record("new number after equals", await result(), "4");
  await click('[data-action="clear-all"]');
  record("AC clears result", await result(), "0");
  record("AC clears expression", await expression(), "");

  await calculate("12+7", "19");
  await captureScreenshot("calculator-19.png");
  const failures = checks.filter(check => !check.passed);
  console.log(JSON.stringify({ browserChecks: checks }, null, 2));
  if (failures.length) throw new Error("Real browser acceptance failed: " + JSON.stringify(failures));
  return { passed: checks.length, checks };
}
